13: class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
14:   static const String _baseCurrency = 'USD';
15: 
16:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
17: 
18:   late final AnimationController _fadeController;
19: 
20:   late Future<List<CurrencyModel>> _currencyListFuture;
21: 
22:   List<CurrencyModel> _allCurrencies = const <CurrencyModel>[];
23: 
24:   int _currentPage = 0;
25: 
26:   bool _hasMore = false;
27: 
28:   @override
29:   void initState() {
30:     super.initState();
31:     WidgetsBinding.instance.addObserver(this);
32:     _initAnimation();
33:     _initData();
34:   }
35: 
36:   @override
37:   void dispose() {
38:     WidgetsBinding.instance.removeObserver(this);
