40:     _fadeController.dispose();
41:     super.dispose();
42:   }
43: 
44:   @override
45:   void didChangeAppLifecycleState(AppLifecycleState state) {
46:     if (state == AppLifecycleState.resumed) _refresh();
47:   }
48: 
49:   void _initAnimation() {
50:     _fadeController = AnimationController(
51:       duration: Duration(milliseconds: 400),
52:       vsync: this,
53:     );
54:   }
55: 
56:   void _initData() {
57:     final currencyRepository = context.read<CurrencyRepository>();
58: 
59:     _filteredCurrenciesNotifier = ValueNotifier(_allCurrencies);
60: 
61:     _currencyListFuture = _loadPage(currencyRepository, const CurrencyPageRequest(base: _baseCurrency)).then((List<CurrencyModel> currencies) {
62:       _fadeController.forward(); // запускаем анимацию
63: 
64:       return currencies;
65:     });
66:   }
67: 
68:   /// Загружает страницу [request] и делает её текущим состоянием списка.
69:   Future<List<CurrencyModel>> _loadPage(CurrencyRepository currencyRepository, CurrencyPageRequest request) async {
70:     final CurrencyPage page = await currencyRepository.fetchRates(request);
71: 
72:     _allCurrencies = page.items;
73:     _filteredCurrenciesNotifier.value = page.items;
74: 
75:     _currentPage = page.page;
76:     _hasMore = page.hasMore;
77: 
78:     currencyRepository.saveCurrencyList(page.items);
79: 
80:     return page.items;
81:   }
82: 
83:   /// Догружает следующую страницу и дописывает её к текущему списку.
84:   Future<void> _loadMore() async {
85:     final currencyRepository = context.read<CurrencyRepository>();
86:     final CurrencyPage page = await currencyRepository.fetchRates(
87:       CurrencyPageRequest(base: _baseCurrency, page: _currentPage + 1),
88:     );
89: 
90:     _allCurrencies = <CurrencyModel>[..._allCurrencies, ...page.items];
91:     _filteredCurrenciesNotifier.value = _allCurrencies;
92: 
93:     _currentPage = page.page;
94:     _hasMore = page.hasMore;
95: 
96:     currencyRepository.saveCurrencyList(page.items);
97:   }
98: 
99:   /// Обновляет список свежим запросом с базовой валютой проекта.
100:   void _refresh() {
101:     final currencyRepository = context.read<CurrencyRepository>();
102: 
103:     setState(() {
104:       _currencyListFuture = _loadPage(currencyRepository, const CurrencyPageRequest(base: _baseCurrency));
105:     });
106:   }
107: 
108:   void _filterCurrencies(String query) {
109:     final String lowerQuery = query.toLowerCase();
110:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
111:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
112:     });
113: 
114:     _filteredCurrenciesNotifier.value = result.toList(growable: false);
115:   }
116: 
117:   Widget _buildShowMoreButton() {
118:     return Padding(
119:       padding: const EdgeInsets.only(top: 20),
120:       child: ElevatedButton(
121:         onPressed: _loadMore,
122:         child: Text(
123:           context.loc.showMore,
124:           style: context.fonts.regular14,
125:         ),
126:       ),
127:     );
128:   }
129: 
130:   @override
131:   Widget build(BuildContext context) {
132:     return Scaffold(
